shader.fragmentShader:
#version 300 es
precision highp float;
in vec2 v_uv;
out vec4 fragColor;
uniform sampler2D u_texA;
uniform sampler2D u_texB;
uniform float u_progress;
void main() {
  float p = u_progress;
  vec2 uvA = v_uv - vec2(p, 0.0);
  vec2 uvB = v_uv + vec2(1.0 - p, 0.0);
  fragColor = p < 0.5 ? texture(u_texA, uvA) : texture(u_texB, uvB);
}
